CREATE COLUMN TABLE "TEST_AP"."OCLS" ("Code" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "Type" SMALLINT CS_INT DEFAULT -1 NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "Active" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCLS_type" ON "TEST_AP"."OCLS" ( "Type" ASC, "Name" ASC )